"#!/usr/bin/env python3
"""
Generate a complete OpenFOAM 10 (Foundation) case for a 3D
Rayleigh-Benard ("Bernard cell") convection simulation using buoyantFoam.

Domain   : 9 m (x) x 1 m (y) x 2 m (z)
Hot wall : bottom (y = 0) at T = 305 K
Cold wall: top    (y = 1) at T = 300 K
Run      : t = 0 -> 1000 s, deltaT = 1 s, write every 50 s

The script only writes files (os + built-ins); it never executes OpenFOAM.
Afterwards run the case with:  ./Allrun
"""

import os


# ---------------------------------------------------------------------------
# helpers
# ---------------------------------------------------------------------------
def write_file(rel_path, content, executable=False):
    """Write `content` to `rel_path`, creating parent directories."""
    directory = os.path.dirname(rel_path)
    if directory:
        os.makedirs(directory, exist_ok=True)
    with open(rel_path, "w") as fh:
        fh.write(content)
    if executable:
        os.chmod(rel_path, 0o755)


def foam_header(obj, cls="dictionary"):
    """Standard FoamFile banner."""
    return (
        "FoamFile\n"
        "{\n"
        "    version     2.0;\n"
        "    format      ascii;\n"
        "    class       " + cls + ";\n"
        "    object      " + obj + ";\n"
        "}\n"
    )


# ===========================================================================
# system/blockMeshDict  (9 m x 1 m x 2 m box, 27 x 9 x 12 = 2916 cells)
# ===========================================================================
write_file(
    "system/blockMeshDict",
    foam_header("blockMeshDict")
    + """
convertToMeters 1;

vertices
(
    (0 0 0)
    (9 0 0)
    (9 1 0)
    (0 1 0)
    (0 0 2)
    (9 0 2)
    (9 1 2)
    (0 1 2)
);

blocks
(
    hex (0 1 2 3 4 5 6 7) (27 9 12) simpleGrading (1 1 1)
);

edges ();

boundary
(
    bottomWall
    {
        type wall;
        faces
        (
            (0 1 5 4)
        );
    }
    topWall
    {
        type wall;
        faces
        (
            (3 7 6 2)
        );
    }
    leftWall
    {
        type wall;
        faces
        (
            (0 4 7 3)
        );
    }
    rightWall
    {
        type wall;
        faces
        (
            (1 2 6 5)
        );
    }
    frontWall
    {
        type wall;
        faces
        (
            (0 3 2 1)
        );
    }
    backWall
    {
        type wall;
        faces
        (
            (4 5 6 7)
        );
    }
);

mergePatchPairs ();

// ************************************************************************* //
""",
)

# ===========================================================================
